function boq(){const {t,D,H,cL,cW,cF,kg}=P,tB=P.tB??t,tT=P.tT??t,tCW=P.tCW??t,tCF=P.tCF??t,tCT=P.tCT??t,R0=D/2,R1=R0+t,PI=Math.PI,ring=PI*(R1*R1-R0*R0)*H,base=PI*R1*R1*tB,lenA=Math.min(3,2*R0*.99),topw=(PI*R1*R1-(lenA*.8+.64*2))*tT;
 const XL=cL+t+tCW,ZW=cW+2*tCW,oa=XL*ZW,cw=(oa-cL*cW)*(H-cF-tCT),cfl=oa*tCF,ctp=(oa-.64)*tCT,fill=oa*cF,conc=ring+base+topw+cw+cfl+ctp;
 const form=2*PI*R0*H+2*PI*R1*H+2*(cL+cW)*(H-cF-tCT)+(XL+ZW)*(H-cF+tCT), wp=2*PI*R1*(H+tB)+PI*R1*R1+2*(XL+ZW)*(H-cF+tCF)+oa;
 const exW=PI/4*Math.pow(2*R1+1,2)*(H-.3+tB),exC=(XL+1)*(ZW+1)*Math.max(0,(H-.3)-(cF-tCF)),exc=exW+exC,back=Math.max(0,exc-(ring+base+cw+cfl));
 return {rows:[['bq_ring',ring,'m³'],['bq_base',base,'m³'],['bq_top',topw,'m³'],['bq_cw',cw,'m³'],['bq_cf',cfl,'m³'],['bq_ct',ctp,'m³']],conc,fill,rebar:conc*kg/1000,form,wp,exc,back};}
